import re, sys
from pathlib import Path

rotos = 0
for f in sys.argv[1:]:
    p = Path(f)
    for destino in re.findall(r"\]\(([^)#]+)", p.read_text()):
        if destino.startswith("http"):
            continue
        if not (p.parent / destino).exists():
            print("ROTO", f, "->", destino)
            rotos += 1
print("enlaces rotos:", rotos)
